input.command:
cd "$PWD"; python3 - <<'EOF'
s=open('index.html').read()
a=s.index("  if ('IntersectionObserver' in window) {\n    var visible = {};")
b=s.index("  /* ---- Post filters ---- */")
new='''  var ticking = false;
  function updateActive() {
    ticking = false;
    var line = window.innerHeight * 0.4;
    var current = null;
    sections.forEach(function (s) { if (s.getBoundingClientRect().top <= line) current = s.id; });
    // At the very bottom of the page, the last section is current.
    if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2) current = sections[sections.length - 1].id;
    navLinks.forEach(function (a) {
      if (current && a.getAttribute('href') === '#' + current) a.setAttribute('aria-current', 'true');
      else a.removeAttribute('aria-current');
    });
  }
  window.addEventListener('scroll', function () {
    if (!ticking) { ticking = true; requestAnimationFrame(updateActive); }
  }, { passive: true });
  window.addEventListener('resize', updateActive);
  updateActive();

'''
s=s[:a]+new+s[b:]
open('index.html','w').write(s)
EOF
"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome" --headless=new --disable-gpu --allow-file-access-from-files --virtual-time-budget=3000 --window-size=1440,2000 --screenshot=/tmp/mlshots/bot3.png file:///tmp/mlshots/bot.html 2>/dev/null; cd /tmp/mlshots && sips -c 70 1440 --cropOffset 0 0 bot3.png --out hdr.png >/dev/null

